/bin/zsh -lc "python3 - <<'PY'
import subprocess,re
commits=subprocess.check_output(['git','rev-list','--all'],text=True).splitlines()
found={}
for c in commits:
 for p in subprocess.check_output(['git','ls-tree','-r','--name-only',c],text=True).splitlines():
  if re.search(r'book|buch|prolog|publication|augmented',p,re.I) and not p.endswith(('.DS_Store','.gitkeep','.zip')):
   b=subprocess.check_output(['git','rev-parse',c+':'+p],text=True).strip()
   found.setdefault((p,b),c)
for (p,b),c in found.items(): print(c[:12],b[:12],p)
PY"
